const devEui = (msg.payload.deviceInfo && msg.payload.deviceInfo.devEui) || null;
if (!devEui) return null;

const registrados = (global.get('sensoresRegistrados') || []).filter(s => s.fuente === 'mqtt' && s.mqttDevEui === devEui && s.habilitado !== false);
if (registrados.length === 0) return null;

function obtenerPorPath(obj, path) {
    return (path || '').split('.').reduce((acc, key) => (acc === undefined || acc === null) ? undefined : acc[key], obj);
}

let lecturas = global.get('lecturasSensores') || {};
let historiales = global.get('historialSensores') || {};
const ahora = Date.now();
const SEIS_HORAS = 6 * 60 * 60 * 1000;
const salidas = [];

registrados.forEach(s => {
    const crudo = obtenerPorPath(msg.payload, s.mqttPath);
    const numero = (crudo === undefined || crudo === null || crudo === '') ? null : Number(crudo);
    const valor = (numero !== null && !isNaN(numero)) ? numero : null;
    const lectura = { sensorId: s.id, nombre: s.nombre, tipo: s.tipo, unidad: s.unidad, valor: valor, ultimaLectura: new Date().toLocaleString() };
    lecturas[s.id] = lectura;
    if (valor !== null) {
        let hist = historiales[s.id] || [];
        hist.push({ t: ahora, valor: valor });
        hist = hist.filter(p => ahora - p.t <= SEIS_HORAS);
        historiales[s.id] = hist;
    }
    salidas.push({ payload: lectura });
});
global.set('lecturasSensores', lecturas);
global.set('historialSensores', historiales);

return [salidas];

msg.headers = { Authorization: 'Bearer ' + env.get('HA_TOKEN') };
msg.url = 'http://homeassistant:8123/api/states';
return msg;

const estados = msg.payload || [];
const registrados = (global.get('sensoresRegistrados') || []).filter(s => s.fuente === 'home_assistant' && s.habilitado !== false);
if (registrados.length === 0) return null;

let lecturas = global.get('lecturasSensores') || {};
let historiales = global.get('historialSensores') || {};
const ahora = Date.now();
const SEIS_HORAS = 6 * 60 * 60 * 1000;
const salidas = [];

registrados.forEach(s => {
    const e = estados.find(x => x.entity_id === s.haEntityId);
    let valor = null;
    if (e && e.state !== 'unknown' && e.state !== 'unavailable') {
        const v = parseFloat(e.state);
        if (!isNaN(v)) valor = v;
    }
    const lectura = { sensorId: s.id, nombre: s.nombre, tipo: s.tipo, unidad: s.unidad, valor: valor, ultimaLectura: new Date().toLocaleString() };
    lecturas[s.id] = lectura;
    if (valor !== null) {
        let hist = historiales[s.id] || [];
        hist.push({ t: ahora, valor: valor });
        hist = hist.filter(p => ahora - p.t <= SEIS_HORAS);
        historiales[s.id] = hist;
    }
    salidas.push({ payload: lectura });
});
global.set('lecturasSensores', lecturas);
global.set('historialSensores', historiales);

return [salidas];

const lectura = msg.payload;
if (!lectura || !lectura.sensorId) return null;

const todasLecturas = global.get('lecturasSensores') || {};
const historiales = global.get('historialSensores') || {};
const lista = Object.values(todasLecturas).map(function(l) {
    return Object.assign({}, l, { historial: (historiales[l.sensorId] || []).map(function(p){ return { t: p.t, valor: p.valor }; }) });
});

return [msg, { payload: lista }];

