function construirEstadoControl() {
    const zonas = flow.get('zonas') || [];
    const valvulas = flow.get('valvulas') || [];
    const config = flow.get('config') || {};
    const abiertas = valvulas.filter(v => v.estado).length;
    const ahora = Date.now();
    return {
        automatico: config.modoAutomatico !== false,
        valvulasAbiertas: abiertas,
        rutinaEnCurso: flow.get('rutinaEnCurso') || null,
        zonas: zonas.map(z => {
            const valvulasZona = valvulas.filter(v => v.zonaId === z.id);
            return {
                id: z.id, nombre: z.nombre, unitid: z.unitid, habilitada: z.habilitada !== false,
                alarma: !!z.alarma,
                maxSimultaneas: z.maxSimultaneas || 1,
                abiertasZona: valvulasZona.filter(v => v.estado).length,
                valvulas: valvulasZona.map(v => {
                    let restanteSeg = null;
                    if (v.estado && v.aperturaDesde && v.duracionMs) {
                        restanteSeg = Math.max(0, Math.round((v.duracionMs - (ahora - v.aperturaDesde)) / 1000));
                    }
                    return { id: v.id, nombre: v.nombre, canal: v.canal, estado: !!v.estado, origen: v.origen || null, restanteSeg: restanteSeg };
                })
            };
        })
    };
}

function construirEstadoConfig() {
    const zonas = flow.get('zonas') || [];
    const valvulas = flow.get('valvulas') || [];
    return {
        zonas: zonas.map(z => ({
            id: z.id, nombre: z.nombre, unitid: z.unitid, canalesTarjeta: z.canalesTarjeta,
            maxSimultaneas: z.maxSimultaneas || 1,
            habilitada: z.habilitada !== false, alarma: !!z.alarma,
            valvulas: valvulas.filter(v => v.zonaId === z.id)
        })),
        config: Object.assign({ watchdogMinutos: 60 }, flow.get('config') || {}),
        nuevaZona: { nombre: '', unitid: null, canalesTarjeta: 8, maxSimultaneas: 1 }, mostrarNuevaZona: false,
        editandoZonaId: null, editandoValvulaId: null,
        nuevaValvulaZonaId: null, nuevaValvula: { nombre: '', canal: 0 },
        menuZonaId: null, confirmarEliminarZonaId: null,
        menuValvulaId: null, confirmarEliminarValvulaId: null,
        sensoresRegistrados: (global.get('sensoresRegistrados') || []).map(s => ({
            id: s.id, nombre: s.nombre, tipo: s.tipo || 'otro', unidad: s.unidad || '',
            fuente: s.fuente, haEntityId: s.haEntityId || '', mqttDevEui: s.mqttDevEui || '', mqttPath: s.mqttPath || '',
            habilitado: s.habilitado !== false
        })),
        nuevoSensor: { nombre: '', tipo: 'temperatura', unidad: '', fuente: 'home_assistant', haEntityId: '', mqttDevEui: '', mqttPath: '' },
        mostrarNuevoSensor: false, editandoSensorId: null, menuSensorId: null, confirmarEliminarSensorId: null,
        hubManaged: !!env.get('HUB_URL')
    };
}

function construirEstadoRutinas() {
    const zonas = flow.get('zonas') || [];
    const valvulas = flow.get('valvulas') || [];
    const rutinas = flow.get('rutinas') || [];
    const diasCortos = { 0: 'Dom', 1: 'Lun', 2: 'Mar', 3: 'Mie', 4: 'Jue', 5: 'Vie', 6: 'Sab' };

    function nombreValvula(id) {
        const v = valvulas.find(x => x.id === id);
        return v ? v.nombre : '?';
    }

    const sensoresRegistrados = global.get('sensoresRegistrados') || [];
    function nombreSensor(id) {
        const s = sensoresRegistrados.find(x => x.id === id);
        return s ? s.nombre : '?';
    }
    function textoCondicion(cond, etiqueta) {
        const opTxt = cond.operador === 'menor' ? '<' : '>';
        const s = sensoresRegistrados.find(x => x.id === cond.sensorId);
        const unidad = s && s.unidad ? (' ' + s.unidad) : '';
        return etiqueta + ' (' + nombreSensor(cond.sensorId) + ') ' + opTxt + ' ' + cond.umbral + unidad;
    }

    const rutinasVista = rutinas.map(r => {
        const startStr = String(r.start || '').padStart(4, '0');
        const endStr = r.end ? String(r.end).padStart(4, '0') : '';
        const sensorPartes = [];
        if (r.usarSensor) {
            if (r.sensorTemp && r.sensorTemp.activa) sensorPartes.push(textoCondicion(r.sensorTemp, 'Temp'));
            if (r.sensorHum && r.sensorHum.activa) sensorPartes.push(textoCondicion(r.sensorHum, 'Hum'));
        }
        const combinadorTxt = r.sensorCombinador === 'y' ? ' Y ' : ' o ';
        return {
            id: r.id, nombre: r.nombre, enabled: r.enabled !== false,
            usarHorario: !!r.usarHorario, usarSensor: !!r.usarSensor,
            horarioTxt: r.usarHorario ? (startStr.slice(0, 2) + ':' + startStr.slice(2) + (r.end ? (' - ' + endStr.slice(0, 2) + ':' + endStr.slice(2)) : '')) : '',
            sensorTxt: sensorPartes.length ? sensorPartes.join(combinadorTxt) : '',
            diasTxt: r.usarHorario ? (r.dias || '').split(',').filter(x => x !== '').map(d => diasCortos[parseInt(d)]).join('/') : '',
            valvulasTxt: (r.valvulaIds || []).map(nombreValvula).join(', '),
            duracionTxt: r.duracion + (r.duracionUnidad === 'segundos' ? 's' : 'min')
        };
    });

    return {
        zonas: zonas.map(z => ({
            id: z.id, nombre: z.nombre,
            valvulas: valvulas.filter(v => v.zonaId === z.id).map(v => ({ id: v.id, nombre: v.nombre }))
        })),
        rutinas: rutinasVista,
        sensoresRegistrados: sensoresRegistrados.map(s => ({ id: s.id, nombre: s.nombre, tipo: s.tipo, unidad: s.unidad })),
        menuRutinaId: null, confirmarEliminarRutinaId: null
    };
}
global.set('rzConstruirEstadoControl', construirEstadoControl);
global.set('rzConstruirEstadoConfig', construirEstadoConfig);
global.set('rzConstruirEstadoRutinas', construirEstadoRutinas);

return null;

let datos = {};
let parseoOk = false;
try {
    datos = JSON.parse(msg.payload) || {};
    parseoOk = true;
} catch (e) {
    node.error('No se pudo leer riego.json, se arranca vacio SIN sobrescribir el archivo: ' + e.message);
    datos = {};
}
flow.set('zonas', Array.isArray(datos.zonas) ? datos.zonas : []);

// Al arrancar SIEMPRE partimos de "todo cerrado": no hay forma de confiar en
// que el estado guardado siga siendo real (el hardware pudo cambiar, o el
// proceso se corto a mitad de un ciclo), y los watchdogs viven en memoria
// asi que no sobreviven un reinicio. Si una rutina realmente debia seguir
// corriendo, el catch-up la vuelve a abrir con su propio watchdog nuevo.
const valvulasCargadas = Array.isArray(datos.valvulas) ? datos.valvulas : [];
const valvulasLimpias = valvulasCargadas.map(v => Object.assign({}, v, {
    estado: false, origen: null, aperturaDesde: null, duracionMs: null
}));
flow.set('valvulas', valvulasLimpias);

flow.set('rutinas', Array.isArray(datos.rutinas) ? datos.rutinas : []);
flow.set('config', Object.assign({ modoAutomatico: true, watchdogMinutos: 60 }, datos.config || {}));
flow.set('fallosZona', {});
if (Array.isArray(datos.sensores)) {
    global.set('sensoresRegistrados', datos.sensores);
}

const msgCron = { payload: flow.get('rutinas') };
// Ya NO se reguarda automaticamente el archivo apenas se carga. Si la
// lectura del archivo fallo o vino vacia por cualquier motivo transitorio
// (ej. justo en el instante del arranque del contenedor), esto evitaba que
// se sobreescribiera el archivo bueno con un estado vacio sin aviso -- asi
// paso una vez y se perdieron rutinas reales. El guardado real sigue
// pasando normalmente con cada accion del usuario (crear/editar/borrar).
return [msgCron, null];

const r = msg.payload;
if (!r || r.enabled === false || !r.usarHorario || r.usarSensor || !r.start) return null;

function hhmm(s) {
    const str = String(s).padStart(4, '0');
    return str.slice(0, 2) + ':' + str.slice(2);
}

function calcularCatchUp(rr) {
    const ahora = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
    const diaHoy = ahora.getDay();
    const diasArr = (rr.dias || '').toString().split(',').filter(x => x !== '').map(Number);
    if (!diasArr.includes(diaHoy)) return false;
    const startStr = String(rr.start).padStart(4, '0');
    const startMin = parseInt(startStr.slice(0, 2), 10) * 60 + parseInt(startStr.slice(2), 10);
    const ahoraMin = ahora.getHours() * 60 + ahora.getMinutes();
    if (rr.end) {
        const endStr = String(rr.end).padStart(4, '0');
        const endMin = parseInt(endStr.slice(0, 2), 10) * 60 + parseInt(endStr.slice(2), 10);
        return ahoraMin >= startMin && ahoraMin < endMin;
    }
    return ahoraMin === startMin;
}

const horaStr = hhmm(r.start);
const [h, m] = horaStr.split(':').map(Number);
const horaFinStr = r.end ? hhmm(r.end) : null;
const totalSel = (r.valvulaIds || []).length;
if (totalSel === 0) return null;
const maxV = Math.max(1, r.maxValvulas || 1);
const modoValvulas = maxV >= totalSel ? 'simultaneo' : (maxV <= 1 ? 'rotacion' : 'maximo');

const cargaUtil = {
    rutinaId: r.id, rutinaNombre: r.nombre,
    tipo: 'pulso', valvulaIds: r.valvulaIds,
    pulsoValor: r.duracion, pulsoUnidad: r.duracionUnidad || 'minutos',
    pausaValor: r.intervalo || 0, pausaUnidad: 'minutos',
    modoValvulas: modoValvulas, maxSimultaneas: maxV,
    modoFin: horaFinStr ? 'horaFin' : 'repeticiones',
    horaFin: horaFinStr, repeticiones: horaFinStr ? null : 1
};

const msgAdd = { payload: { command: 'add', name: 'rutina_' + r.id, topic: 'rutina_' + r.id, expressionType: 'cron', expression: m + ' ' + h + ' * * ' + r.dias, payloadType: 'json', payload: cargaUtil, timezone: 'America/New_York' } };

let msgCatchUp = null;
if (calcularCatchUp(r)) {
    node.warn('Recuperando rutina en curso tras reinicio: ' + r.nombre);
    msgCatchUp = { payload: cargaUtil };
}

return [msgAdd, msgCatchUp];

const lecturas = global.get('lecturasSensores') || {};
function valorSensor(sensorId) {
    const l = lecturas[sensorId];
    return (l && l.valor !== null && l.valor !== undefined) ? l.valor : null;
}
const rutinas = flow.get('rutinas') || [];
const armadas = flow.get('sensorRutinasArmadas') || {};

function estaEnVentana(r) {
    if (!r.usarHorario) return true;
    const ahora = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
    const diasArr = (r.dias || '').toString().split(',').filter(x => x !== '').map(Number);
    if (diasArr.length && !diasArr.includes(ahora.getDay())) return false;
    const nowMin = ahora.getHours() * 60 + ahora.getMinutes();
    const startStr = String(r.start || '0000').padStart(4, '0');
    const startMin = parseInt(startStr.slice(0, 2), 10) * 60 + parseInt(startStr.slice(2), 10);
    const endStr = r.end ? String(r.end).padStart(4, '0') : '2359';
    const endMin = parseInt(endStr.slice(0, 2), 10) * 60 + parseInt(endStr.slice(2), 10);
    return nowMin >= startMin && nowMin <= endMin;
}

function cumpleSensor(r) {
    if (!r.usarSensor) return true;
    const checks = [];
    if (r.sensorTemp && r.sensorTemp.activa && r.sensorTemp.sensorId) {
        const v = valorSensor(r.sensorTemp.sensorId);
        if (v === null || isNaN(v)) {
            checks.push(false);
        } else {
            checks.push(r.sensorTemp.operador === 'menor' ? v < r.sensorTemp.umbral : v > r.sensorTemp.umbral);
        }
    }
    if (r.sensorHum && r.sensorHum.activa && r.sensorHum.sensorId) {
        const v = valorSensor(r.sensorHum.sensorId);
        if (v === null || isNaN(v)) {
            checks.push(false);
        } else {
            checks.push(r.sensorHum.operador === 'menor' ? v < r.sensorHum.umbral : v > r.sensorHum.umbral);
        }
    }
    if (checks.length === 0) return false;
    return r.sensorCombinador === 'y' ? checks.every(Boolean) : checks.some(Boolean);
}

const salidas = [];
rutinas.forEach(r => {
    if (!r.enabled || !r.usarSensor) return; // las de horario puro las maneja el cron, no esta funcion

    const disparar = estaEnVentana(r) && cumpleSensor(r);

    if (disparar && !armadas[r.id]) {
        // Flanco de subida: se dispara una sola vez, se rearma cuando deja
        // de cumplirse la condicion (o se sale de la ventana horaria).
        armadas[r.id] = true;
        const totalSel = (r.valvulaIds || []).length;
        const maxV = Math.max(1, r.maxValvulas || 1);
        const cargaUtil = {
            rutinaId: r.id, rutinaNombre: r.nombre,
            tipo: 'pulso', valvulaIds: r.valvulaIds,
            pulsoValor: r.duracion, pulsoUnidad: r.duracionUnidad || 'minutos',
            pausaValor: r.intervalo || 0, pausaUnidad: 'minutos',
            modoValvulas: maxV >= totalSel ? 'simultaneo' : (maxV <= 1 ? 'rotacion' : 'maximo'),
            maxSimultaneas: maxV,
            modoFin: 'repeticiones', horaFin: null, repeticiones: 1
        };
        node.warn('Rutina por sensor disparada: ' + r.nombre);
        salidas.push({ payload: cargaUtil });
    } else if (!disparar && armadas[r.id]) {
        armadas[r.id] = false;
    }
});
flow.set('sensorRutinasArmadas', armadas);
return salidas.length ? [salidas] : null;

const cfg = msg.payload;

function delay(ms) { return new Promise(resolve => setTimeout(resolve, ms)); }
function aMs(valor, unidad) {
    if (unidad === 'horas') return valor * 3600000;
    if (unidad === 'minutos') return valor * 60000;
    return valor * 1000;
}
function chunk(arr, size) {
    const out = [];
    for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
    return out;
}
function dentroDeVentana(horaFin) {
    const ahora = new Date();
    const [hf, mf] = horaFin.split(':').map(Number);
    const fin = new Date(ahora);
    fin.setHours(hf, mf, 0, 0);
    return ahora < fin;
}

// Evita que la misma rutina quede corriendo dos veces en paralelo (por
// ejemplo si el catch-up de un reinicio y el cron normal coinciden, o si
// cron-plus reintenta un disparo). Sin esto, dos ciclos concurrentes sobre
// las mismas valvulas pueden pisarse el abrir/cerrar entre si.
const rutinasCorriendo = flow.get('rutinasCorriendo') || {};
if (cfg.rutinaId && rutinasCorriendo[cfg.rutinaId]) {
    node.warn('Rutina "' + cfg.rutinaNombre + '" ya esta en ejecucion, se ignora este disparo duplicado');
    return null;
}
if (cfg.rutinaId) {
    rutinasCorriendo[cfg.rutinaId] = true;
    flow.set('rutinasCorriendo', rutinasCorriendo);
}

const pulsoMs = aMs(cfg.pulsoValor, cfg.pulsoUnidad || 'minutos');
const pausaMs = aMs(cfg.pausaValor, cfg.pausaUnidad || 'minutos');
const lista = cfg.valvulaIds || [];

function abrir(id) { node.send([{ payload: { accion: 'abrir', valvulaId: id, origen: 'auto', duracionMs: pulsoMs } }, null]); }
function cerrar(id) { node.send([{ payload: { accion: 'cerrar', valvulaId: id, origen: 'auto' } }, null]); }

function avisarPanel() {
    const construirControl = global.get('rzConstruirEstadoControl');
    if (!construirControl) return;
    node.send([null, { payload: construirControl() }]);
}

flow.set('rutinaEnCurso', { id: cfg.rutinaId, nombre: cfg.rutinaNombre, desde: Date.now() });
avisarPanel();

async function correrCiclo() {
    let ronda = 0;
    while (true) {
        ronda++;
        // El intervalo se cuenta desde que arranca ESTA ronda (el primer
        // grupo), no desde que termina la ultima valvula. Asi "10s cada
        // 30s" significa un ciclo completo cada 30s, no 10s + 30s extra.
        const inicioRonda = Date.now();

        if (cfg.modoValvulas === 'simultaneo') {
            lista.forEach(abrir);
            await delay(pulsoMs);
            lista.forEach(cerrar);
        } else if (cfg.modoValvulas === 'maximo') {
            const grupos = chunk(lista, Math.max(1, cfg.maxSimultaneas || 1));
            for (const grupo of grupos) {
                grupo.forEach(abrir);
                await delay(pulsoMs);
                grupo.forEach(cerrar);
            }
        } else {
            for (const id of lista) {
                abrir(id);
                await delay(pulsoMs);
                cerrar(id);
            }
        }

        if (cfg.modoFin === 'repeticiones') {
            if (ronda >= cfg.repeticiones) break;
        } else if (cfg.modoFin === 'horaFin') {
            if (!dentroDeVentana(cfg.horaFin)) break;
        }

        const transcurrido = Date.now() - inicioRonda;
        const esperaRestante = Math.max(0, pausaMs - transcurrido);
        await delay(esperaRestante);
        if (cfg.modoFin === 'horaFin' && !dentroDeVentana(cfg.horaFin)) break;
    }
    node.warn('Rutina de riego finalizada (' + lista.length + ' valvula(s))');
    flow.set('rutinaEnCurso', null);
    if (cfg.rutinaId) {
        const activas = flow.get('rutinasCorriendo') || {};
        delete activas[cfg.rutinaId];
        flow.set('rutinasCorriendo', activas);
    }
    avisarPanel();
}

correrCiclo();
return null;

const datos = {
    zonas: flow.get('zonas') || [],
    valvulas: flow.get('valvulas') || [],
    rutinas: flow.get('rutinas') || [],
    config: flow.get('config') || {},
    sensores: global.get('sensoresRegistrados') || []
};
msg.payload = JSON.stringify(datos, null, 2);
return msg;

const d = msg.payload;
const config = flow.get('config') || {};
const zonas = flow.get('zonas') || [];
let valvulas = flow.get('valvulas') || [];

const valvula = valvulas.find(v => v.id === d.valvulaId);
if (!valvula) { node.warn('Valvula no encontrada: ' + d.valvulaId); return null; }
const zona = zonas.find(z => z.id === valvula.zonaId);
if (!zona) { node.warn('Zona no encontrada para valvula ' + valvula.nombre); return null; }

// El modo Automatico solo bloquea APERTURAS disparadas por rutinas.
// Los cierres (y el watchdog de seguridad) siempre se ejecutan.
if (d.accion === 'abrir' && d.origen === 'auto' && config.modoAutomatico === false) {
    return null;
}

if (d.accion === 'abrir') {
    const abiertasZona = valvulas.filter(v => v.zonaId === zona.id && v.estado).length;
    const maxZona = zona.maxSimultaneas || 1;
    if (!valvula.estado && abiertasZona >= maxZona) {
        node.warn('Limite de ' + maxZona + ' valvula(s) simultaneas alcanzado en zona "' + zona.nombre + '", se ignora apertura de ' + valvula.nombre);
        return [null, { payload: 'Limite de ' + maxZona + ' valvula(s) simultaneas en ' + zona.nombre + ' alcanzado' }, null, null];
    }
}

// Actualizacion optimista: la UI refleja el comando apenas se envia, sin
// esperar confirmacion de Modbus (asi funciona aunque el gateway este
// caido). La lectura periodica y la alarma de zona siguen mostrando por
// separado si el hardware realmente responde o no.
const idx = valvulas.findIndex(v => v.id === valvula.id);
const abre = d.accion === 'abrir';
// Duracion esperada de esta apertura: la trae la rutina (pulso) o, si no,
// el auto-apagado de seguridad propio del actuador (valvula.autoApagadoSeg
// en segundos -- pensado para motores sin limite fisico confiable, ej.
// cortinas). Una apertura manual comun sin ninguno de los dos usa el
// watchdog largo de la zona (config.watchdogMinutos).
const duracionEfectivaMs = d.duracionMs || (valvula.autoApagadoSeg ? valvula.autoApagadoSeg * 1000 : null);
valvulas[idx] = Object.assign({}, valvulas[idx], {
    estado: abre,
    origen: abre ? (d.origen || 'manual') : null,
    aperturaDesde: (abre && duracionEfectivaMs) ? Date.now() : null,
    duracionMs: (abre && duracionEfectivaMs) ? duracionEfectivaMs : null
});
flow.set('valvulas', valvulas);

let watchdogs = context.get('watchdogs') || {};
if (watchdogs[valvula.id]) {
    clearTimeout(watchdogs[valvula.id]);
    delete watchdogs[valvula.id];
}
if (d.accion === 'abrir') {
    // Si hay una duracion efectiva (pulso de rutina o auto-apagado propio
    // del actuador), el watchdog de esa valvula es corto: duracion +
    // margen. Esto es una red de seguridad independiente del cerrar()
    // normal, por si ese mensaje se pierde, el ciclo se interrumpe, o el
    // limite fisico del motor falla. Sin ninguna duracion efectiva, usa el
    // watchdog largo configurable de la zona.
    const minutosLargo = config.watchdogMinutos || 60;
    const minutos = duracionEfectivaMs ? Math.max(0.25, (duracionEfectivaMs / 60000) + 0.5) : minutosLargo;
    const nombreValvula = valvula.nombre;
    const idValvula = valvula.id;
    watchdogs[idValvula] = setTimeout(() => {
        node.warn('Cierre de seguridad (watchdog) activado para: ' + nombreValvula);
        node.send([null, null, null, { payload: { accion: 'cerrar', valvulaId: idValvula, origen: 'watchdog' } }]);
    }, minutos * 60000);
}
context.set('watchdogs', watchdogs);

const construirControl = global.get('rzConstruirEstadoControl');
const msgPanel = construirControl ? { payload: construirControl() } : null;

msg.valvulaId = valvula.id;
msg.accionSolicitada = d.accion;
msg.origenSolicitado = d.origen || 'manual';
msg.payload = { value: d.accion === 'abrir', unitid: zona.unitid, fc: 5, address: valvula.canal, quantity: 1 };
return [msg, null, msgPanel, null];

const id = msg.valvulaId;
const accion = msg.accionSolicitada;
const origen = msg.origenSolicitado;
let valvulas = flow.get('valvulas') || [];
const idx = valvulas.findIndex(v => v.id === id);
if (idx === -1) return null;

valvulas[idx] = Object.assign({}, valvulas[idx], { estado: accion === 'abrir', origen: accion === 'abrir' ? origen : null });
flow.set('valvulas', valvulas);

const zonaId = valvulas[idx].zonaId;
let fallos = flow.get('fallosZona') || {};
fallos[zonaId] = 0;
flow.set('fallosZona', fallos);

const construirControl = global.get('rzConstruirEstadoControl');
return { payload: construirControl() };

const id = msg.valvulaId;
let valvulas = flow.get('valvulas') || [];
const valvula = valvulas.find(v => v.id === id);
if (!valvula) return null;

let fallos = flow.get('fallosZona') || {};
fallos[valvula.zonaId] = (fallos[valvula.zonaId] || 0) + 1;
flow.set('fallosZona', fallos);

if (fallos[valvula.zonaId] >= 3) {
    let zonas = flow.get('zonas') || [];
    const zidx = zonas.findIndex(z => z.id === valvula.zonaId);
    if (zidx !== -1 && !zonas[zidx].alarma) {
        zonas[zidx] = Object.assign({}, zonas[zidx], { alarma: true });
        flow.set('zonas', zonas);
        node.warn('ALARMA de comunicacion en zona: ' + zonas[zidx].nombre);
    }
}

const construirControl = global.get('rzConstruirEstadoControl');
msg.payload = construirControl();
return msg;

const zonas = (flow.get('zonas') || []).filter(z => z.habilitada !== false);
if (zonas.length === 0) return null;
msg.payload = zonas.map(z => ({ zonaId: z.id, unitid: z.unitid, canalesTarjeta: z.canalesTarjeta }));
return msg;

const z = msg.payload;
msg.zonaId = z.zonaId;
msg.payload = { fc: 1, unitid: z.unitid, address: 0, quantity: Math.max(1, z.canalesTarjeta || 8) };
return msg;

const zonaId = msg.zonaId;
const lecturas = msg.payload;
let valvulas = flow.get('valvulas') || [];
let cambios = false;

valvulas = valvulas.map(v => {
    if (v.zonaId !== zonaId) return v;
    const real = !!(lecturas && lecturas[v.canal]);
    if (real !== !!v.estado) {
        cambios = true;
        return Object.assign({}, v, { estado: real, origen: real ? (v.origen || 'auto') : null });
    }
    return v;
});
if (cambios) flow.set('valvulas', valvulas);

let fallos = flow.get('fallosZona') || {};
fallos[zonaId] = 0;
flow.set('fallosZona', fallos);

let zonas = flow.get('zonas') || [];
const zidx = zonas.findIndex(z => z.id === zonaId);
if (zidx !== -1 && zonas[zidx].alarma) {
    zonas[zidx] = Object.assign({}, zonas[zidx], { alarma: false });
    flow.set('zonas', zonas);
    node.warn('Zona recuperada (comunicacion OK): ' + zonas[zidx].nombre);
    cambios = true;
}

if (!cambios) return null;
const construirControl = global.get('rzConstruirEstadoControl');
msg.payload = construirControl();
return msg;

const zonaId = msg.zonaId;
if (zonaId === undefined) return null;

let fallos = flow.get('fallosZona') || {};
fallos[zonaId] = (fallos[zonaId] || 0) + 1;
flow.set('fallosZona', fallos);

if (fallos[zonaId] >= 3) {
    let zonas = flow.get('zonas') || [];
    const zidx = zonas.findIndex(z => z.id === zonaId);
    if (zidx !== -1 && !zonas[zidx].alarma) {
        zonas[zidx] = Object.assign({}, zonas[zidx], { alarma: true });
        flow.set('zonas', zonas);
        node.warn('ALARMA de comunicacion (lectura) en zona id ' + zonaId);
        const construirControl = global.get('rzConstruirEstadoControl');
        msg.payload = construirControl();
        return msg;
    }
}
return null;

const construirControl = global.get('rzConstruirEstadoControl');
msg.payload = construirControl();
return msg;

const id = msg.payload.valvulaId;
const valvulas = flow.get('valvulas') || [];
const v = valvulas.find(x => x.id === id);
if (!v) return null;
msg.payload = { accion: v.estado ? 'cerrar' : 'abrir', valvulaId: id, origen: 'manual' };
return msg;

let config = flow.get('config') || {};
config.modoAutomatico = !!msg.payload.valor;
flow.set('config', config);
return {};

const construirConfig = global.get('rzConstruirEstadoConfig');
msg.payload = construirConfig();
return msg;

const d = msg.payload;
const zonas = flow.get('zonas') || [];

const faltantes = [];
if (!d.nombre || !d.nombre.trim()) faltantes.push('nombre');
if (d.unitid === undefined || d.unitid === null || d.unitid === '') faltantes.push('unit id (Modbus)');
if (!d.canalesTarjeta || d.canalesTarjeta < 1) faltantes.push('cantidad de canales de la tarjeta');
if (faltantes.length) return [null, null, { payload: 'Falta: ' + faltantes.join(', ') }];

const unitidNum = Number(d.unitid);
if (zonas.some(z => Number(z.unitid) === unitidNum)) {
    return [null, null, { payload: 'Ya existe una zona con Unit ID ' + unitidNum }];
}

const nueva = {
    id: Date.now(), nombre: d.nombre.trim(), unitid: unitidNum,
    canalesTarjeta: Number(d.canalesTarjeta), maxSimultaneas: Math.max(1, Number(d.maxSimultaneas) || 1),
    habilitada: true, alarma: false
};
zonas.push(nueva);
flow.set('zonas', zonas);

const construirConfig = global.get('rzConstruirEstadoConfig');
return [{ payload: construirConfig() }, {}, { payload: 'Zona creada: ' + nueva.nombre }];

const d = msg.payload;
let zonas = flow.get('zonas') || [];
const idx = zonas.findIndex(z => z.id === d.id);
if (idx === -1) return [null, null, { payload: 'Zona no encontrada' }];

const faltantes = [];
if (!d.nombre || !d.nombre.trim()) faltantes.push('nombre');
if (d.unitid === undefined || d.unitid === null || d.unitid === '') faltantes.push('unit id');
if (!d.canalesTarjeta || d.canalesTarjeta < 1) faltantes.push('canales');
if (faltantes.length) return [null, null, { payload: 'Falta: ' + faltantes.join(', ') }];

const unitidNum = Number(d.unitid);
if (zonas.some((z, i) => i !== idx && Number(z.unitid) === unitidNum)) {
    return [null, null, { payload: 'Ya existe otra zona con ese Unit ID' }];
}

zonas[idx] = Object.assign({}, zonas[idx], {
    nombre: d.nombre.trim(), unitid: unitidNum, canalesTarjeta: Number(d.canalesTarjeta),
    maxSimultaneas: Math.max(1, Number(d.maxSimultaneas) || 1),
    habilitada: d.habilitada !== false
});
flow.set('zonas', zonas);

const construirConfig = global.get('rzConstruirEstadoConfig');
return [{ payload: construirConfig() }, {}, { payload: 'Zona actualizada: ' + zonas[idx].nombre }];

const id = msg.payload.id;
let zonas = flow.get('zonas') || [];
const valvulas = flow.get('valvulas') || [];
const zona = zonas.find(z => z.id === id);
if (!zona) return [null, null, { payload: 'Zona no encontrada' }];

if (valvulas.some(v => v.zonaId === id)) {
    return [null, null, { payload: 'No se puede eliminar "' + zona.nombre + '": primero elimina sus valvulas' }];
}

zonas = zonas.filter(z => z.id !== id);
flow.set('zonas', zonas);

const construirConfig = global.get('rzConstruirEstadoConfig');
return [{ payload: construirConfig() }, {}, { payload: 'Zona eliminada: ' + zona.nombre }];

const d = msg.payload;
const zonas = flow.get('zonas') || [];
let valvulas = flow.get('valvulas') || [];

const zona = zonas.find(z => z.id === d.zonaId);
if (!zona) return [null, null, { payload: 'Selecciona una zona valida' }];

const faltantes = [];
if (!d.nombre || !d.nombre.trim()) faltantes.push('nombre');
if (d.canal === undefined || d.canal === null || d.canal === '') faltantes.push('canal');
if (faltantes.length) return [null, null, { payload: 'Falta: ' + faltantes.join(', ') }];

const canalNum = Number(d.canal);
if (canalNum < 0 || canalNum >= zona.canalesTarjeta) {
    return [null, null, { payload: 'Canal fuera de rango (0 a ' + (zona.canalesTarjeta - 1) + ') para ' + zona.nombre }];
